/** П1 «Как курица лапкой»: Миша (1) and his partner (2) check their lists against each other; T is the teacher.
 *  Lines p1-01…p1-31 in order; p1-32 Миша greets a teacher who came in openly, p1-33 asks them instead of the call (15–17);
 *  p1-tq the teacher asks what the question is, p1-ta the ready answer. Text: ~/temp/П1-курица.txt */
/** gap: ms after the line before the next, if set in the voice editor (else the engine's own) */
export interface DialogueLine { id: string; who: 1 | 2 | 'T'; write: string | null; ms: Record<string, number>; text: string; gap?: number }
/** П4 «Трёп»: they begin checking (p4-01…07), drift into chatter by who sits there — м-м p4-08…29 football, ж-ж p4-30…47
 *  the party, ж-м p4-48…69 the rabbit (1 the girl) — and wake up at the end (p4-70…76, one writes out their list);
 *  a teacher coming in openly before that gets p4-77…89 instead: they check for real. Text: ~/temp/П4-трёп.txt */
export const CHAT: DialogueLine[] = [
  {"id":"p4-01","who":1,"write":null,"ms":{"kirill":1567,"zahar":1567,"alexander":1593,"filipp":1567,"ermil":1384,"lera":1620,"dasha":1646,"masha":1724,"jane":1332},"text":"Ну что, сверяемся?"},
  {"id":"p4-02","who":2,"write":null,"ms":{"zahar":1672,"kirill":1698,"filipp":1776,"ermil":1489,"alexander":1698,"dasha":1776,"lera":1855,"masha":1750,"jane":1567},"text":"Давай. У тебя сколько?"},
  {"id":"p4-03","who":1,"write":null,"ms":{"kirill":2429,"alexander":2482,"ermil":2456,"zahar":2560,"dasha":2456,"lera":2508,"filipp":2508,"masha":2638,"jane":2586},"text":"Четыре. Стороны и диагонали."},
  {"id":"p4-04","who":2,"write":null,"ms":{"kirill":5512,"alexander":5172,"ermil":5486,"zahar":5355,"filipp":5538,"dasha":5329,"lera":5433,"jane":5355,"masha":5721},"text":"У меня тоже четыре, только другие. Стороны есть, диагоналей нет. Зато углы."},
  {"id":"p4-05","who":1,"write":null,"ms":{"kirill":6217,"alexander":5878,"ermil":5878,"zahar":5982,"dasha":5799,"filipp":5851,"lera":6165,"masha":5669,"jane":5642},"text":"Угол. А. равен углу цэ, — вижу. А внизу что? Это бэ или восьмёрка?"},
  {"id":"p4-06","who":2,"write":null,"ms":{"kirill":2821,"alexander":2508,"ermil":2638,"zahar":2638,"filipp":2795,"dasha":2560,"lera":2691,"masha":2743,"jane":2456},"text":"Бэ. Угол бэ равен углу дэ."},
  {"id":"p4-07","who":1,"write":null,"ms":{"kirill":4571,"alexander":4336,"ermil":4310,"zahar":4415,"filipp":4415,"dasha":4336,"lera":4467,"masha":4598,"jane":4336},"text":"Ну и почерк. Ладно, значит, вместе у нас… раз, два…"},
  {"id":"p4-08","who":2,"write":null,"ms":{"kirill":2168,"alexander":2194,"ermil":2142,"zahar":2064,"filipp":2299},"text":"Слушай, а ты в субботу чего не пришёл?"},
  {"id":"p4-09","who":1,"write":null,"ms":{"kirill":3683,"alexander":3553,"ermil":3500,"zahar":3762,"filipp":3579},"text":"Не пустили, бабушка приезжала. Ну и как сыграли?"},
  {"id":"p4-10","who":2,"write":null,"ms":{"kirill":888,"alexander":862,"ermil":836,"zahar":888,"filipp":993},"text":"Семь — пять."},
  {"id":"p4-11","who":1,"write":null,"ms":{"kirill":810,"alexander":679,"zahar":888,"ermil":705,"filipp":836},"text":"Кто кого?"},
  {"id":"p4-12","who":2,"write":null,"ms":{"kirill":810,"alexander":758,"ermil":758,"zahar":758,"filipp":836},"text":"Они нас."},
  {"id":"p4-13","who":1,"write":null,"ms":{"kirill":1959,"alexander":1985,"ermil":1776,"zahar":2038,"filipp":2064},"text":"Семь?! А кто на воротах стоял?"},
  {"id":"p4-14","who":2,"write":null,"ms":{"kirill":601,"alexander":575,"ermil":575,"zahar":653,"filipp":627},"text":"Костя."},
  {"id":"p4-15","who":1,"write":null,"ms":{"kirill":1672,"alexander":1541,"ermil":1724,"zahar":1698,"filipp":1750},"text":"А, ну тогда всё понятно."},
  {"id":"p4-16","who":2,"write":null,"ms":{"kirill":7732,"alexander":7236,"ermil":7471,"zahar":7602,"filipp":8072},"text":"Да там вообще... А за них ещё Рустам пришёл, здоровый такой. Он точно в восьмом? Кажется, что ему лет восемнадцать."},
  {"id":"p4-17","who":1,"write":null,"ms":{"kirill":1358,"zahar":1254,"alexander":1332,"ermil":1306,"filipp":1411},"text":"Это который с бородой?"},
  {"id":"p4-18","who":2,"write":null,"ms":{"kirill":4754,"alexander":4624,"zahar":4728,"ermil":4728,"filipp":4833},"text":"С бородой. Мы говорим: так нечестно. А он: «Борода не играет»."},
  {"id":"p4-19","who":1,"write":null,"ms":{"kirill":1541,"alexander":1515,"zahar":1411,"ermil":1463,"filipp":1515},"text":"Мда, гениально."},
  {"id":"p4-20","who":2,"write":null,"ms":{"kirill":10553,"alexander":9718,"ermil":9691,"zahar":9378,"filipp":10658},"text":"А последний гол - просто песня. Костя начал мяч выносить и прямо Максу в спину попал. А от него — под удар их нападающему. Ну и всё, семь — пять."},
  {"id":"p4-21","who":1,"write":null,"ms":{"kirill":1985,"alexander":1776,"ermil":1985,"zahar":1750,"filipp":2038},"text":"То есть Костя им ещё и помог."},
  {"id":"p4-22","who":2,"write":null,"ms":{"kirill":1750,"alexander":1593,"ermil":1698,"zahar":1672,"filipp":1881},"text":"Он сказал, это тактика была."},
  {"id":"p4-23","who":1,"write":null,"ms":{"kirill":1071,"alexander":1097,"ermil":1019,"zahar":1176,"filipp":1228},"text":"Какая тактика?"},
  {"id":"p4-24","who":2,"write":null,"ms":{"kirill":2064,"alexander":2116,"ermil":2090,"zahar":2168,"filipp":2220},"text":"Не знаю. Он сам не знает."},
  {"id":"p4-25","who":1,"write":null,"ms":{"kirill":1332,"alexander":1228,"ermil":1176,"zahar":1202,"filipp":1437},"text":"В эту субботу идём?"},
  {"id":"p4-26","who":2,"write":null,"ms":{"kirill":2664,"alexander":2612,"ermil":2664,"zahar":2743,"filipp":2900},"text":"Идём. Только Костю на ворота не ставим."},
  {"id":"p4-27","who":1,"write":null,"ms":{"kirill":1123,"alexander":1097,"ermil":1045,"zahar":1149,"filipp":1202},"text":"Давай я встану."},
  {"id":"p4-28","who":2,"write":null,"ms":{"kirill":4650,"alexander":4258,"ermil":4310,"zahar":4336,"filipp":4780},"text":"Ты? Ты в прошлый раз в воротах спиной стоял, с кем-то по телефону болтал."},
  {"id":"p4-29","who":1,"write":null,"ms":{"kirill":1254,"alexander":1176,"zahar":1280,"ermil":1202,"filipp":1306},"text":"Это мама звонила!"},
  {"id":"p4-30","who":2,"write":null,"ms":{"dasha":2011,"lera":2273,"masha":2299,"jane":1776},"text":"Слушай, а ты у Кати до конца была?"},
  {"id":"p4-31","who":1,"write":null,"ms":{"dasha":3500,"lera":3396,"masha":3579,"jane":3135},"text":"Нет, меня в девять забрали. А что? Что-то было?"},
  {"id":"p4-32","who":2,"write":null,"ms":{"dasha":2952,"lera":2978,"masha":3082,"jane":2769},"text":"Было. Лёша пришёл. В белой рубашке."},
  {"id":"p4-33","who":1,"write":null,"ms":{"dasha":1933,"lera":1985,"masha":2064,"jane":1959},"text":"В белой? На день рождения?"},
  {"id":"p4-34","who":2,"write":null,"ms":{"dasha":5172,"lera":5303,"masha":5460,"jane":5486},"text":"Да. И стоит у стены. Весь вечер стоит. Все танцуют, а он стоит."},
  {"id":"p4-35","who":1,"write":null,"ms":{"dasha":1437,"lera":1541,"masha":1489,"jane":1384},"text":"Ну! это Лёша."},
  {"id":"p4-36","who":2,"write":null,"ms":{"dasha":6426,"lera":6844,"masha":7053,"jane":6583},"text":"Подожди. И тут Катя включает ту песню. Ну, которую она всё время слушает. И идёт прямо к нему."},
  {"id":"p4-37","who":1,"write":null,"ms":{"dasha":888,"lera":940,"masha":914,"jane":836},"text":"Да ладно!"},
  {"id":"p4-38","who":2,"write":null,"ms":{"dasha":2247,"lera":2351,"masha":2377,"jane":2351},"text":"А он отходит и наливает себе сок."},
  {"id":"p4-39","who":1,"write":null,"ms":{"dasha":575,"lera":627,"masha":601,"jane":575},"text":"Чево?!"},
  {"id":"p4-40","who":2,"write":null,"ms":{"dasha":4650,"lera":4676,"masha":4989,"jane":4754},"text":"Он думал, она к столу идёт. Отошёл, чтобы не мешать. И налил себе сок."},
  {"id":"p4-41","who":1,"write":null,"ms":{"dasha":1019,"lera":1045,"masha":1071,"jane":1019},"text":"Не может быть!"},
  {"id":"p4-42","who":2,"write":null,"ms":{"dasha":5538,"lera":5616,"masha":5878,"jane":5512},"text":"Может. Она так и стоит посреди комнаты. Потом говорит: «Лёш, я вообще-то к тебе»."},
  {"id":"p4-43","who":1,"write":null,"ms":{"dasha":627,"lera":601,"masha":575,"jane":601},"text":"А он?"},
  {"id":"p4-44","who":2,"write":null,"ms":{"dasha":1437,"lera":1567,"masha":1515,"jane":1384},"text":"А он ей: «Будешь сок?»"},
  {"id":"p4-45","who":1,"write":null,"ms":{"dasha":3500,"lera":3605,"masha":3579,"jane":2873},"text":"Всё! Не могу! И что, танцевали в итоге?"},
  {"id":"p4-46","who":2,"write":null,"ms":{"lera":5956,"dasha":5878,"masha":6400,"jane":5904},"text":"Танцевали. Он ей на ногу пару раз наступил, вроде. А она потом сказала, что это было мило."},
  {"id":"p4-47","who":1,"write":null,"ms":{"dasha":1829,"lera":1829,"masha":1881,"jane":1776},"text":"Мило… Ну Катя даёт."},
  {"id":"p4-48","who":1,"write":null,"ms":{"dasha":1802,"lera":1985,"masha":2064,"jane":1907},"text":"А у нас вчера кролик появился."},
  {"id":"p4-49","who":2,"write":null,"ms":{"kirill":1254,"alexander":1176,"ermil":1254,"zahar":1306,"filipp":1411},"text":"В смысле — появился."},
  {"id":"p4-50","who":1,"write":null,"ms":{"dasha":3631,"lera":3840,"masha":3997,"jane":3840},"text":"Родители купили. Младшей сестре, у неё день рождения."},
  {"id":"p4-51","who":2,"write":null,"ms":{"kirill":1019,"alexander":1019,"ermil":862,"zahar":1045,"filipp":967},"text":"Настоящий?"},
  {"id":"p4-52","who":1,"write":null,"ms":{"dasha":4859,"lera":5068,"masha":5277,"jane":4911},"text":"Нет, плюшевый. Конечно, настоящий. Серый. Уши большие такие."},
  {"id":"p4-53","who":2,"write":null,"ms":{"kirill":914,"alexander":914,"zahar":993,"ermil":862,"filipp":940},"text":"Как назвали?"},
  {"id":"p4-54","who":1,"write":null,"ms":{"dasha":1881,"lera":1933,"masha":1959,"jane":1907},"text":"Она назвала. Пельмень."},
  {"id":"p4-55","who":2,"write":null,"ms":{"kirill":1045,"ermil":914,"alexander":1019,"zahar":993,"filipp":1097},"text":"Почему Пельмень?"},
  {"id":"p4-56","who":1,"write":null,"ms":{"dasha":2900,"lera":2586,"masha":2926,"jane":2482},"text":"Говорит, похож. Сидит, — и правда похож."},
  {"id":"p4-57","who":2,"write":null,"ms":{"kirill":1567,"alexander":1437,"ermil":1515,"zahar":1541,"filipp":1620},"text":"А ты как хотела назвать?"},
  {"id":"p4-58","who":1,"write":null,"ms":{"dasha":2090,"lera":2142,"masha":2168,"jane":2194},"text":"Граф. Но кто меня спрашивал."},
  {"id":"p4-59","who":2,"write":null,"ms":{"kirill":1071,"alexander":1045,"ermil":993,"zahar":1071,"filipp":1176},"text":"Граф Пельмень."},
  {"id":"p4-60","who":1,"write":null,"ms":{"dasha":5251,"masha":5564,"lera":5512,"jane":5198},"text":"О. Так и будем звать. Только он ночью провод от зарядки перегрыз. Мой."},
  {"id":"p4-61","who":2,"write":null,"ms":{"kirill":914,"alexander":914,"ermil":862,"filipp":914,"zahar":1045},"text":"А мама что?"},
  {"id":"p4-62","who":1,"write":null,"ms":{"lera":5068,"dasha":4937,"masha":5381,"jane":5016},"text":"Мама говорит: «Сами хотели кролика». А я не хотела! Это сестра хотела."},
  {"id":"p4-63","who":2,"write":null,"ms":{"kirill":1541,"alexander":1541,"ermil":1515,"zahar":1593,"filipp":1724},"text":"И как теперь без зарядки?"},
  {"id":"p4-64","who":1,"write":null,"ms":{"dasha":2325,"lera":2429,"masha":2508,"jane":2351},"text":"Взяла папину. Он пока не знает."},
  {"id":"p4-65","who":2,"write":null,"ms":{"kirill":1620,"alexander":1567,"ermil":1463,"zahar":1541,"filipp":1750},"text":"А его на руки брать можно?"},
  {"id":"p4-66","who":1,"write":null,"ms":{"dasha":7732,"lera":7837,"masha":8516,"jane":7993},"text":"Можно, только он лягается. Сестра посадила его в кукольную коляску, а он выпрыгнул и под диван. Час доставали."},
  {"id":"p4-67","who":2,"write":null,"ms":{"kirill":731,"alexander":679,"ermil":601,"zahar":810,"filipp":731},"text":"Покажешь?"},
  {"id":"p4-68","who":1,"write":null,"ms":{"lera":3109,"dasha":2821,"masha":3187,"jane":3004},"text":"Приходи. Только за зарядкой своей в оба смотри."},
  {"id":"p4-69","who":2,"write":null,"ms":{"kirill":1541,"alexander":1411,"ermil":1463,"zahar":1437,"filipp":1620},"text":"Хорошо, договорились."},
  {"id":"p4-70","who":1,"write":null,"ms":{"kirill":2325,"alexander":2142,"ermil":2064,"zahar":2351,"filipp":2325,"dasha":2142,"lera":2456,"masha":2403,"jane":2064},"text":"Ой, смотри, время заканчивается."},
  {"id":"p4-71","who":2,"write":null,"ms":{"kirill":2090,"ermil":2247,"alexander":1959,"zahar":2011,"filipp":2220,"dasha":1933,"lera":2064,"masha":2168,"jane":1959},"text":"Мы же так ничего и не проверили."},
  {"id":"p4-72","who":1,"write":"AD = BC; AB = CD; AO = OC; BO = OD","ms":{"kirill":2900,"alexander":2717,"ermil":2717,"zahar":2795,"filipp":2978,"dasha":2821,"lera":2952,"masha":3082,"jane":2769},"text":"Давай я просто своё выпишу. Там всё нормально."},
  {"id":"p4-73","who":2,"write":null,"ms":{"kirill":940,"alexander":940,"ermil":836,"zahar":1045,"filipp":914,"dasha":888,"lera":914,"masha":940,"jane":836},"text":"А мои углы?"},
  {"id":"p4-74","who":1,"write":null,"ms":{"kirill":862,"alexander":888,"ermil":784,"zahar":967,"filipp":940,"dasha":888,"lera":967,"masha":940,"jane":862},"text":"Это какие?"},
  {"id":"p4-75","who":2,"write":null,"ms":{"kirill":2534,"alexander":2273,"ermil":2273,"zahar":2273,"dasha":2273,"filipp":2247,"lera":2377,"masha":2325,"jane":2168},"text":"Угол. А. равен углу цэ."},
  {"id":"p4-76","who":1,"write":"∠A = ∠C","ms":{"kirill":993,"alexander":940,"ermil":940,"zahar":1019,"filipp":1097,"lera":993,"dasha":993,"masha":993,"jane":888},"text":"Хорошо, берём."},
  {"id":"p4-77","who":"T","write":null,"ms":{"alena":2508,"anton":2403},"text":"Так, как у вас дела? Проверили уже?"},
  {"id":"p4-78","who":1,"write":null,"ms":{"kirill":3553,"alexander":3396,"zahar":3500,"filipp":3527,"ermil":3161,"dasha":3396,"lera":3474,"masha":3683,"jane":3370},"text":"Здравствуйте, Татьяна Алексеевна. Да… почти."},
  {"id":"p4-79","who":2,"write":null,"ms":{"kirill":810,"ermil":784,"alexander":758,"zahar":836,"dasha":810,"filipp":836,"lera":810,"masha":862,"jane":784},"text":"Проверяем..."},
  {"id":"p4-80","who":"T","write":null,"ms":{"alena":8255,"anton":8098},"text":"Что-то у вас доска совсем пустая. Нужно уже ускоряться. По очереди, по одному наблюдению, и сразу записывайте. Всё понятно?"},
  {"id":"p4-81","who":1,"write":null,"ms":{"kirill":2168,"alexander":2038,"zahar":1881,"ermil":2011,"dasha":2064,"filipp":2168,"lera":2142,"masha":2116,"jane":1698},"text":"Да, сейчас. Начинаем."},
  {"id":"p4-82","who":2,"write":"AD = BC","ms":{"kirill":1306,"zahar":1306,"filipp":1384,"alexander":1332,"ermil":1358,"dasha":1306,"lera":1358,"masha":1384,"jane":1332},"text":"А-дэ равно бэ-цэ."},
  {"id":"p4-83","who":1,"write":"AB = CD","ms":{"kirill":1254,"zahar":1280,"filipp":1358,"alexander":1202,"ermil":1306,"lera":1280,"dasha":1202,"masha":1332,"jane":1280},"text":"А-бэ равно цэ-дэ."},
  {"id":"p4-84","who":2,"write":"∠A = ∠C","ms":{"kirill":3918,"alexander":3579,"ermil":3553,"dasha":3605,"zahar":3448,"filipp":3683,"lera":3866,"jane":3553,"masha":3788},"text":"Угол. А. равен углу цэ. Этого у тебя не было."},
  {"id":"p4-85","who":1,"write":"AO = OC","ms":{"kirill":3396,"alexander":3265,"ermil":3187,"zahar":3265,"dasha":3109,"filipp":3318,"lera":3291,"masha":3474,"jane":3344},"text":"Тогда а-о равно о-цэ. А этого не было у тебя."},
  {"id":"p4-86","who":2,"write":"∠B = ∠D","ms":{"kirill":3553,"alexander":3318,"ermil":3500,"zahar":3553,"filipp":3527,"dasha":3344,"lera":3500,"masha":3683,"jane":3422},"text":"Угол бэ равен углу дэ. Та самая «восьмёрка»."},
  {"id":"p4-87","who":1,"write":"BO = OD","ms":{"kirill":1620,"zahar":1593,"filipp":1593,"alexander":1463,"ermil":1463,"dasha":1411,"lera":1541,"masha":1567,"jane":1437},"text":"Бэ-о равно о-дэ."},
  {"id":"p4-88","who":2,"write":null,"ms":{"kirill":3370,"alexander":3161,"ermil":3265,"zahar":3265,"dasha":3265,"filipp":3500,"lera":3291,"masha":3527,"jane":3239},"text":"Смотри: у каждого было по четыре, а вместе — шесть."},
  {"id":"p4-89","who":1,"write":null,"ms":{"kirill":1202,"alexander":1176,"zahar":1280,"ermil":1149,"filipp":1228,"dasha":1228,"lera":1254,"masha":1228,"jane":1071},"text":"Да, отлично."},
];
