export const TRAP: TrapLine[] = [
  {"id":"c1-01","who":1,"write":null,"ms":{"kirill":2273,"zahar":2273,"filipp":2299,"alexander":2299,"ermil":2090},"text":"Привет! Все тут? Всех слышно?"},
  {"id":"c1-02","who":2,"write":null,"ms":{"kirill":2325,"zahar":2168,"alexander":2325,"ermil":2116,"filipp":2403,"dasha":2273,"lera":2273,"masha":2403,"jane":2168},"text":"Слышно. Только у кого-то эхо."},
  {"id":"c1-03","who":4,"write":null,"ms":{"kirill":2429,"alexander":2325,"filipp":2508,"zahar":2429,"ermil":2403,"dasha":2377,"lera":2534,"masha":2482,"jane":2325},"text":"Это не эхо. Это брат за стенкой."},
  {"id":"c1-04","who":1,"write":null,"ms":{"kirill":2952,"alexander":2900,"ermil":2664,"zahar":2926,"filipp":2900},"text":"Ладно. Карточки по кругу. Кто первый?"},
  {"id":"c1-05","who":3,"write":null,"ms":{"kirill":2691,"zahar":2482,"alexander":2456,"ermil":2560,"filipp":2691,"dasha":2508,"lera":2612,"masha":2664,"jane":2403},"text":"Давай ты. Ты всё равно уже командуешь."},
  {"id":"c1-06","who":1,"write":null,"ms":{"kirill":8307,"zahar":8281,"alexander":8124,"filipp":8594,"ermil":8176},"text":"Я не командую, я организую. Первая. А-бэ параллельна цэ-дэ, и а-бэ равно цэ-дэ. Первый признак. Да."},
  {"id":"c1-07","who":2,"write":null,"ms":{"kirill":5721,"alexander":5486,"ermil":5355,"zahar":5695,"filipp":5799,"dasha":5747,"lera":5616,"masha":6060,"jane":5773},"text":"Согласен. Вторая моя. Стороны попарно равны. Второй признак, тоже да."},
  {"id":"c1-08","who":3,"write":null,"ms":{"kirill":8098,"zahar":7993,"alexander":7837,"filipp":8072,"ermil":7628,"dasha":7863,"lera":8020,"masha":8647,"jane":7811},"text":"Третья. А-бэ параллельна цэ-дэ, бэ-цэ равно а-дэ. Наверно, да. Звучит почти как первая карточка."},
  {"id":"c1-09","who":1,"write":null,"ms":{"kirill":2429,"zahar":2403,"filipp":2534,"alexander":2325,"ermil":2247},"text":"Кидай в столбик да, быстрее закончим."},
  {"id":"c1-10","who":2,"write":null,"ms":{"kirill":8202,"alexander":7393,"zahar":7523,"ermil":8098,"filipp":8307,"dasha":7549,"lera":7680,"masha":8098,"jane":7941},"text":"Подождите. В первой одна и та же пара — и параллельна, и равна. А тут параллельна одна пара, а равна другая."},
  {"id":"c1-11","who":3,"write":null,"ms":{"kirill":627,"alexander":627,"ermil":653,"zahar":731,"filipp":653,"dasha":653,"lera":653,"masha":653,"jane":575},"text":"И что?"},
  {"id":"c1-12","who":2,"write":null,"ms":{"kirill":2586,"alexander":2534,"ermil":2560,"zahar":2534,"filipp":2638,"dasha":2534,"lera":2691,"masha":2691,"jane":2560},"text":"Не знаю что. Но это не то же самое."},
  {"id":"c1-13","who":1,"write":null,"ms":{"kirill":2064,"zahar":2011,"filipp":2168,"ermil":2038,"alexander":1881},"text":"Ну нарисуй тогда, раз не то же."},
  {"id":"c1-14","who":2,"write":null,"ms":{"kirill":5016,"zahar":5016,"alexander":4859,"filipp":5251,"lera":5198,"dasha":5042,"ermil":4833,"masha":5277,"jane":4937},"text":"Сейчас… Нет. Опять параллелограмм получился."},
  {"id":"c1-15","who":1,"write":null,"ms":{"kirill":2743,"zahar":2795,"filipp":2873,"alexander":2717,"ermil":2638},"text":"Вот. Не получается, — значит, да."},
  {"id":"c1-16","who":2,"write":null,"ms":{"kirill":3370,"zahar":3318,"filipp":3474,"ermil":3344,"alexander":3500,"lera":3474,"dasha":3291,"jane":3318,"masha":3631},"text":"Это значит, что у меня не получается. А не что «да»."},
  {"id":"c1-17","who":4,"write":null,"ms":{"kirill":2664,"zahar":2664,"alexander":2664,"ermil":2534,"filipp":2743,"dasha":2717,"lera":2795,"masha":2873,"jane":2638},"text":"Красиво сказано. Записываю в цитаты."},
  {"id":"c1-18","who":1,"write":null,"ms":{"kirill":5433,"zahar":5564,"filipp":5773,"alexander":5172,"ermil":5094},"text":"Слушайте, время идёт, а мы на третьей карточке. Давайте учителя позовём и дальше."},
  {"id":"c1-t0","who":"T","write":null,"ms":{"alena":1959,"anton":1881},"text":"Да. Какие у вас вопросы?"},
  {"id":"c1-19","who":1,"write":null,"ms":{"kirill":8751,"zahar":8281,"filipp":8882,"ermil":8098,"alexander":8176},"text":"Карточка три. Очень похоже на первый признак, но не то же самое. А нарисовать, чтобы получился не параллелограмм, не можем."},
  {"id":"c1-ta1","who":"T","write":null,"ms":{"alena":4989,"anton":4833},"text":"Это непростой вопрос. На него можно ответить, нарисовав то, что дано в условии."},
  {"id":"c1-ta2","who":"T","write":null,"ms":{"alena":5460,"anton":5277},"text":"Смотрите. Нарисуем две параллельные прямые — ведь а-бэ параллельна цэ-дэ.","gap":200},
  {"id":"c1-ta3","who":"T","write":null,"ms":{"alena":2873,"anton":3030},"text":"На одной отметим а и бэ. Вот так.","gap":200},
  {"id":"c1-ta4","who":"T","write":null,"ms":{"alena":2508,"anton":2403},"text":"На другой — точку цэ. Например, здесь.","gap":200},
  {"id":"c1-ta5","who":"T","write":null,"ms":{"alena":4807,"anton":5042},"text":"Осталось понять, где может быть точка дэ, чтобы а-дэ равнялось бэ-цэ.","gap":200},
  {"id":"c1-ta6","who":"T","write":null,"ms":{"alena":1515,"anton":1463},"text":"Теперь подумайте сами.","gap":1000},
  {"id":"c1-20","who":2,"write":null,"ms":{"kirill":8803,"zahar":8542,"filipp":8934,"alexander":8202,"lera":8647,"ermil":8176,"dasha":8359,"masha":9064,"jane":8542},"text":"Точно, дэ может быть здесь и здесь. И когда здесь, это трапеция! Равнобокая. Боковые стороны равны, а основания параллельны."},
  {"id":"c1-tok","who":"T","write":null,"ms":{"alena":1411,"anton":1358},"text":"Молодец, правильно."},
  {"id":"c1-21","who":3,"write":null,"ms":{"kirill":4467,"alexander":4180,"ermil":4206,"zahar":4232,"filipp":4493,"dasha":4075,"masha":4493,"lera":4310,"jane":4127},"text":"Ой. И правда. Параллельна одна пара, а равна другая.","gap":700},
  {"id":"c1-22","who":1,"write":null,"ms":{"kirill":3631,"zahar":3474,"alexander":3422,"filipp":3579,"ermil":3579},"text":"Ладно. Перекладываю в «не обязательно». Ты был прав.","gap":700},
  {"id":"c1-22f","who":1,"write":null,"ms":{"kirill":3788,"zahar":3631,"filipp":3657,"alexander":3553,"ermil":3736},"text":"Ладно. Перекладываю в «не обязательно». Ты была права.","gap":700},
  {"id":"c1-23","who":3,"write":null,"ms":{"kirill":5303,"alexander":4937,"ermil":4911,"zahar":4963,"filipp":5355,"dasha":4989,"lera":5120,"masha":5486,"jane":5120},"text":"Четвёртая моя. Диагонали делятся пополам. Это третий признак. Да."},
  {"id":"c1-24","who":4,"write":null,"ms":{"kirill":5930,"alexander":5251,"ermil":5460,"zahar":5146,"filipp":6113,"dasha":5172,"lera":5486,"masha":5564,"jane":5251},"text":"Пятую и шестую — все вместе. Пятая: а-о равно о-цэ, а бэ-о не равно о-дэ."},
  {"id":"c1-25","who":2,"write":null,"ms":{"kirill":6844,"alexander":6296,"ermil":6504,"zahar":6348,"filipp":7210,"dasha":6478,"lera":6583,"masha":6975,"jane":6870},"text":"Тут осторожно. Если бы обе диагонали делились пополам — был бы параллелограмм. А тут только одна."},
  {"id":"c1-26","who":1,"write":null,"ms":{"kirill":3082,"filipp":3239,"alexander":2926,"zahar":2926,"ermil":2795},"text":"Значит, нет? Только теперь сразу с рисунком."},
  {"id":"c1-27","who":2,"write":null,"ms":{"kirill":6844,"alexander":6269,"ermil":6478,"zahar":6557,"filipp":7288,"dasha":6557,"lera":6713,"masha":6896,"jane":6687},"text":"Вот такой. Как воздушный змей. Одна диагональ делит другую пополам, а сама пополам не делится."},
  {"id":"c1-28","who":4,"write":null,"ms":{"kirill":1907,"ermil":1750,"alexander":1985,"zahar":2011,"dasha":1933,"filipp":1985,"lera":1985,"masha":2038,"jane":1881},"text":"Змей. А с хвостом можно?"},
  {"id":"c1-29","who":2,"write":null,"ms":{"zahar":2011,"kirill":1985,"filipp":2038,"alexander":2011,"lera":2090,"ermil":1959,"dasha":1985,"masha":2064,"jane":1933},"text":"Можно и с хвостом. Держи."},
  {"id":"c1-30","who":3,"write":null,"ms":{"kirill":6034,"alexander":5642,"zahar":5669,"ermil":5825,"filipp":6060,"dasha":5904,"lera":6087,"masha":6269,"jane":5878},"text":"Шестая. Противоположные углы равны. Это вроде свойство. А признака такого не было."},
  {"id":"c1-31","who":1,"write":null,"ms":{"kirill":1437,"alexander":1411,"ermil":1254,"zahar":1437,"filipp":1620},"text":"Значит, не обязательно?"},
  {"id":"c1-32","who":2,"write":null,"ms":{"kirill":7549,"alexander":7079,"ermil":7053,"zahar":6870,"dasha":7131,"filipp":7889,"lera":7236,"masha":7680,"jane":6975},"text":"После тройки я без рисунка ничего не кладу. Давайте нарисуем, где углы так равны, а это не параллелограмм."},
  {"id":"c1-33","who":4,"write":null,"ms":{"kirill":4624,"zahar":4519,"alexander":4362,"filipp":4702,"ermil":4571,"dasha":4493,"lera":4545,"masha":4702,"jane":4624},"text":"Не выходит. Всегда параллелограммы получаются, или углы не равны."},
  {"id":"c1-34","who":3,"write":null,"ms":{"kirill":862,"alexander":888,"zahar":888,"filipp":940,"ermil":836,"dasha":862,"lera":993,"masha":940,"jane":862},"text":"У меня тоже."},
  {"id":"c1-35","who":1,"write":null,"ms":{"kirill":1802,"filipp":1802,"zahar":1750,"alexander":1855,"ermil":1620},"text":"Тогда да? Рискнём?"},
  {"id":"c1-36","who":2,"write":null,"ms":{"kirill":2508,"alexander":2429,"ermil":2456,"zahar":2403,"filipp":2586,"dasha":2403,"lera":2586,"masha":2586,"jane":2560},"text":"Рискнём. Но я потом спрошу, почему."},
  {"id":"c1-37","who":4,"write":null,"ms":{"kirill":2038,"zahar":2090,"alexander":2011,"filipp":2090,"ermil":1985,"dasha":1959,"lera":2064,"masha":2142,"jane":1881},"text":"Всё! Все шесть разложили."},
  {"id":"c1-38","who":1,"write":null,"ms":{"kirill":5486,"zahar":5590,"alexander":5381,"filipp":5642,"ermil":5172},"text":"Слушайте, время идёт, а мы на третьей карточке. Татьяна Алексеевна, можно вопрос?"},
  {"id":"c1-39","who":1,"write":null,"ms":{"kirill":9038,"alexander":8359,"zahar":8333,"ermil":8150,"filipp":9012},"text":"Карточка три. Очень похоже на первый признак, но не то же самое. А нарисовать, чтобы получился не параллелограмм, не можем."},
];
