export const SIXTH: FourLine[] = [
  {"id":"c2-01","who":1,"write":null,"ms":{"kirill":2220,"zahar":2194,"alexander":2116,"filipp":2325,"ermil":2011,"dasha":2142,"masha":2247,"lera":2168,"jane":2116},"text":"Первая, — да. Первый признак."},
  {"id":"c2-02","who":2,"write":null,"ms":{"kirill":6034,"zahar":6034,"filipp":6478,"alexander":5851,"masha":6217,"ermil":6008,"dasha":5904,"lera":6191,"jane":5982},"text":"Вторая... Так... Какие у нас ещё признаки?... Это второй признак - переносим в да."},
  {"id":"c2-03","who":3,"write":null,"ms":{"kirill":5512,"zahar":5433,"ermil":5355,"alexander":5303,"filipp":5695,"dasha":5486,"masha":5956,"lera":5486,"jane":5616},"text":"Третья — на первую похожа, только пара букв переставлена местами. Скорее всего - да."},
  {"id":"c2-04","who":1,"write":null,"ms":{"kirill":3500,"zahar":3265,"filipp":3866,"alexander":3631,"ermil":3318,"dasha":3527,"masha":3814,"lera":3474,"jane":3344},"text":"Тогда странно, а почему их в один признак не объединить?"},
  {"id":"c2-05","who":3,"write":null,"ms":{"kirill":3370,"zahar":3370,"filipp":3448,"ermil":3291,"alexander":3187,"dasha":3422,"lera":3474,"masha":3527,"jane":3344},"text":"Не знаю, не догадались, наверно. Надо нарисовать."},
  {"id":"c2-06","who":3,"write":null,"ms":{"kirill":6922,"zahar":6818,"alexander":6531,"ermil":6504,"filipp":7105,"dasha":6583,"lera":6792,"masha":7131,"jane":6687},"text":"Одна прямая... Вторая... Вот а-бэ. И одинаковая с ней цэ-дэ. Вроде как, параллелограмм."},
  {"id":"c2-07","who":1,"write":null,"ms":{"kirill":3082,"zahar":2926,"filipp":3213,"alexander":2900,"ermil":2926,"dasha":2978,"lera":3004,"masha":3109,"jane":3004},"text":"А если в другую сторону наклонить? Вот так."},
  {"id":"c2-08","who":3,"write":null,"ms":{"kirill":3631,"zahar":3736,"ermil":3605,"filipp":3944,"alexander":3605,"dasha":3631,"lera":3709,"masha":3944,"jane":3605},"text":"Точно! Тогда не параллелограмм. Значит, третья — нет."},
  {"id":"c2-09","who":4,"write":null,"ms":{"dasha":2873,"lera":2900,"masha":3056,"jane":2795},"text":"Четвёртая, — да, это просто третий признак."},
  {"id":"c2-10","who":2,"write":null,"ms":{"kirill":2847,"filipp":2926,"zahar":2926,"alexander":2586,"ermil":2743,"dasha":2743,"lera":2795,"masha":2952,"jane":2795},"text":"Пятая. Диагонали, — только одна пополам."},
  {"id":"c2-11","who":1,"write":null,"ms":{"zahar":5042,"kirill":5460,"filipp":5433,"alexander":4989,"ermil":5172,"dasha":5198,"lera":5381,"masha":5538,"jane":5277},"text":"Неверно, скорее всего. Это же от прошлого вопроса половину условия убрали."},
  {"id":"c2-12","who":3,"write":null,"ms":{"kirill":6348,"zahar":6269,"ermil":6060,"filipp":6635,"alexander":6087,"dasha":6165,"masha":6557,"lera":6426,"jane":6165},"text":"Давай нарисую. Эта пополам. А этот не равен этому. Ну да, не похож на параллелограмм."},
  {"id":"c2-13","who":1,"write":null,"ms":{"kirill":5564,"zahar":5277,"filipp":5564,"alexander":5198,"ermil":5120,"dasha":5120,"lera":5381,"masha":5616,"jane":5460},"text":"Так, шестая. Угол а равен углу цэ, угол бэ равен углу дэ."},
  {"id":"c2-14","who":2,"write":null,"ms":{"zahar":4232,"kirill":4310,"filipp":4467,"alexander":4153,"ermil":4023,"dasha":4310,"masha":4571,"lera":4441,"jane":3918},"text":"Это свойство. Но признаков таких не было. Значит не обязательно?"},
  {"id":"c2-15","who":3,"write":null,"ms":{"kirill":3527,"zahar":3370,"filipp":3631,"ermil":3448,"alexander":3344,"lera":3553,"dasha":3396,"masha":3631,"jane":3605},"text":"Если не обязательно, надо пример нарисовать. Нарисуй."},
  {"id":"c2-16","who":2,"write":null,"ms":{"kirill":10188,"zahar":9509,"alexander":9665,"filipp":10292,"ermil":9535,"masha":10606,"dasha":9953,"lera":10188,"jane":9953},"text":"Сейчас попробую. Вот первый угол. От этого луча второй. От этого — третий под таким же углом. Нет. Четвёртый угол первому не равен."},
  {"id":"c2-17","who":1,"write":null,"ms":{"kirill":10815,"zahar":10344,"filipp":11128,"alexander":10083,"ermil":10136,"lera":10527,"dasha":10240,"masha":10815,"jane":10527},"text":"Может, по-другому? Нарисую сразу равные противоположные углы. Один... второй... Тут они пересекаются. И здесь тоже, оставшиеся углы не равны."},
  {"id":"c2-18","who":3,"write":null,"ms":{"kirill":1829,"zahar":1959,"filipp":1959,"ermil":1698,"alexander":1802,"dasha":1855,"lera":2038,"masha":1985,"jane":1776},"text":"Да как это нарисовать-то можно?"},
  {"id":"c2-19","who":1,"write":null,"ms":{"kirill":3135,"zahar":3135,"filipp":3135,"alexander":3004,"ermil":3082,"dasha":3109,"lera":3291,"masha":3344,"jane":3082},"text":"Аня, а ты что думаешь? Ты что-то совсем молчишь."},
  {"id":"c2-20","who":4,"write":null,"ms":{"dasha":6452,"lera":6531,"masha":6766,"jane":6269},"text":"Тоже пока не знаю. Может, просто посчитать? Ну, углов четыре, вместе — триста шестьдесят."},
  {"id":"c2-21","who":1,"write":null,"ms":{"kirill":1620,"zahar":1593,"filipp":1593,"alexander":1567,"ermil":1541,"dasha":1567,"lera":1646,"masha":1593,"jane":1515},"text":"Да, но это везде так."},
  {"id":"c2-22","who":4,"write":null,"ms":{"dasha":5825,"lera":5982,"masha":6243,"jane":5904},"text":"А равен цэ, бэ равен дэ. Значит, а плюс бэ — это половина. Сто восемьдесят."},
  {"id":"c2-23","who":2,"write":null,"ms":{"kirill":1620,"zahar":1724,"filipp":1750,"ermil":1567,"alexander":1672,"dasha":1698,"masha":1855,"lera":1776,"jane":1515},"text":"Интересно, и что с этого?"},
  {"id":"c2-24","who":4,"write":null,"ms":{"dasha":9509,"lera":9744,"masha":10371,"jane":9900},"text":"А и бэ стоят на одной стороне а-бэ. Если в сумме сто восемьдесят — это односторонние углы. Значит, а-дэ параллельна бэ-цэ."},
  {"id":"c2-25","who":3,"write":null,"ms":{"kirill":3030,"zahar":3187,"ermil":2926,"filipp":3187,"alexander":3004,"dasha":3030,"lera":3187,"masha":3265,"jane":3030},"text":"Точно! Эврика! А со второй парой так же!"},
  {"id":"c2-26","who":4,"write":null,"ms":{"dasha":5825,"lera":5982,"jane":5747,"masha":6139},"text":"Да, так же. Значит, обе пары параллельны. И это просто параллелограмм по определению."},
  {"id":"c2-27","who":1,"write":null,"ms":{"kirill":1045,"zahar":1071,"filipp":1097,"alexander":993,"ermil":993,"dasha":967,"lera":1071,"masha":1123,"jane":1045},"text":"Шестая — да!"},
  {"id":"c2-28","who":2,"write":null,"ms":{"kirill":1907,"zahar":1802,"filipp":1829,"alexander":1802,"ermil":1750,"dasha":1724,"masha":1855,"lera":1802,"jane":1750},"text":"Ура! Шесть из шести!"},
  {"id":"c2-29","who":3,"write":null,"ms":{"kirill":1149,"zahar":1202,"filipp":1254,"ermil":993,"alexander":1071,"dasha":1149,"lera":1228,"masha":1202,"jane":1123},"text":"Давайте пятюню!","gap":4600},
  {"id":"c2-30","who":1,"write":null,"ms":{"kirill":1829,"zahar":1855,"filipp":1959,"alexander":1829,"ermil":1776,"dasha":1907,"lera":1985,"masha":2064,"jane":1881},"text":"Аня, что ты раньше молчала?","gap":700},
  {"id":"c2-31","who":4,"write":null,"ms":{"dasha":4049,"lera":4284,"masha":4493,"jane":4310},"text":"Тоже не знала, как решать. Только когда начала объяснять, все сложилось."},
];
